class Solution {
public:
    int minAbsDifference(vector<int>& nums, int goal) {
        int n = nums.size();
        int half = n / 2;

        vector<long long> left;
        left.push_back(0);
        for (int i = 0; i < half; i++) {
            int sz = left.size();
            for (int j = 0; j < sz; j++) {
                left.push_back(left[j] + nums[i]);
            }
        }

        vector<long long> right;
        right.push_back(0);
        for (int i = half; i < n; i++) {
            int sz = right.size();
            for (int j = 0; j < sz; j++) {
                right.push_back(right[j] + nums[i]);
            }
        }

        sort(left.begin(), left.end());

        long long ans = 1000000000000LL;
        for (long long x : right) {
            long long target = (long long)goal - x;
            auto it = lower_bound(left.begin(), left.end(), target);
            if (it != left.end()) {
                long long diff = *it - target;
                if (diff < 0) diff = -diff;
                if (diff < ans) ans = diff;
            }
            if (it != left.begin()) {
                --it;
                long long diff = *it - target;
                if (diff < 0) diff = -diff;
                if (diff < ans) ans = diff;
            }
        }
        return (int)ans;
    }
};
